const listGrants = `-- name: ListGrants :many
WITH RECURSIVE user_groups (
    group_id
) AS (
    SELECT
        id
    FROM
        GROUPS
    WHERE
        deleted_at IS NULL
        AND id IN (
            SELECT
                group_id
            FROM
                group_users
            WHERE
                user_id = $1
                AND removed_at IS NULL)
        UNION
        SELECT
            parent.id
        FROM
            GROUPS g
            JOIN user_groups ug ON ug.group_id = g.id
            JOIN GROUPS parent ON parent.id = g.parent_id
        WHERE
            g.deleted_at IS NULL
            AND parent.deleted_at IS NULL
)
SELECT
    jsonb_build_object('kind', resource_type, 'id', resource_id, 'required',
	bool_or(usage_requirement = 'required'))
FROM
    resource_access_grants rag
WHERE
    (rag.all_users AND EXISTS (
        SELECT 1 FROM users u WHERE u.id = $1 AND u.status = 'active' AND u.deleted_at IS NULL
    ))
    OR rag.user_id = $1
    OR rag.group_id IN (
        SELECT
            group_id
        FROM
            user_groups)
GROUP BY
    resource_type,
    resource_id
`

